package com.pridesys.ticketing.module.controller;import com.pridesys.ticketing.dto.*;import com.pridesys.ticketing.entity.*;import com.pridesys.ticketing.repository.UserRepository;import com.pridesys.ticketing.module.service.ModuleService;import com.pridesys.ticketing.security.util.JwtService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;
@RestController@RequestMapping("/api/projects/{projectId}/modules")public class ModuleController{private final UserRepository users;private final ModuleService service;public ModuleController(UserRepository u,ModuleService s){users=u;service=s;}private UserEntity actor(Authentication a){return users.findById(((JwtService.UserPrincipal)a.getPrincipal()).id()).orElseThrow();}@GetMapping public List<ModuleRecord> list(Authentication a,@PathVariable long projectId){return service.list(actor(a),projectId);}@PostMapping public ModuleRecord create(Authentication a,@PathVariable long projectId,@Valid@RequestBody UsersProjectsDtos.CreateModuleRequest r){return service.create(actor(a),projectId,r);}@PatchMapping("/{id}")public Map<String,String> update(Authentication a,@PathVariable long projectId,@PathVariable long id,@Valid@RequestBody UsersProjectsDtos.UpdateModuleRequest r){service.update(actor(a),projectId,id,r);return Map.of("message","Module updated");}@DeleteMapping("/{id}")public Map<String,String> delete(Authentication a,@PathVariable long projectId,@PathVariable long id){service.delete(actor(a),projectId,id);return Map.of("message","Module deleted");}}
